//! Code emission: render a `Model` as a `kinematics.rs` of `const` data in
//! terms of the `kinematics` crate's types.

use std::fmt::Write as _;

use crate::extract::Model;

pub(crate) fn emit(model: &Model, source: &str) -> String {
    let mut s = String::new();
    let _ = writeln!(
        s,
        "// @generated by `mjcf` from `{source}` — do not edit by hand.\n\
         // Joint frames: frame_i = frame_(i-1) * translate(offset) * rotate(quat) * rotate(axis, q_i).\n\
         // Metres and radians; quaternions are (w, x, y, z).\n\
         \n\
         use kinematics::prelude::{{Joint, Quat, Vec3}};\n"
    );

    let _ = writeln!(
        s,
        "pub const MODEL: &str = {:?};",
        model.model_name.clone().unwrap_or_default()
    );
    let _ = writeln!(s, "pub const SOURCE: &str = {source:?};");
    let _ = writeln!(s, "pub const NJ: usize = {};", model.joints.len());
    let _ = writeln!(s, "pub const NU: usize = {};", model.nu);
    let _ = writeln!(s, "pub const NQ: usize = {};", model.nq);
    match &model.home_q {
        Some(home) => {
            let values: Vec<String> = home.iter().map(|v| f32l(*v)).collect();
            let _ = writeln!(
                s,
                "pub const HOME_Q: Option<[f32; NJ]> = Some([{}]);",
                values.join(", ")
            );
        }
        None => {
            let _ = writeln!(s, "pub const HOME_Q: Option<[f32; NJ]> = None;");
        }
    }
    let names: Vec<String> = model.joints.iter().map(|j| format!("{:?}", j.name)).collect();
    let _ = writeln!(s, "pub const NAMES: [&str; NJ] = [{}];", names.join(", "));
    let ctrls: Vec<String> = model.joints.iter().map(|j| ctrl_opt(j.ctrl)).collect();
    let _ = writeln!(s, "pub const CTRL: [Option<u32>; NJ] = [{}];", ctrls.join(", "));
    let _ = writeln!(s, "pub const JOINTS: [Joint; NJ] = [");
    for j in &model.joints {
        let _ = writeln!(
            s,
            "    Joint {{ offset: Vec3({}), quat: Quat({}), axis: Vec3({}), range: {} }},",
            arr(&j.offset),
            arr(&j.quat),
            arr(&j.axis),
            range_opt(j.range),
        );
    }
    let _ = writeln!(s, "];");
    let _ = writeln!(
        s,
        "pub const TIP_OFFSET: Vec3 = Vec3({});",
        arr(&model.tip_offset)
    );
    let _ = writeln!(
        s,
        "pub const TIP_QUAT: Quat = Quat({});",
        arr(&model.tip_quat)
    );
    s
}

fn f32l(x: f64) -> String {
    let x = x as f32;
    format!("{:?}", if x == 0.0 { 0.0 } else { x })
}

fn arr<const N: usize>(v: &[f64; N]) -> String {
    let values: Vec<String> = v.iter().map(|x| f32l(*x)).collect();
    format!("[{}]", values.join(", "))
}

fn range_opt(r: Option<[f64; 2]>) -> String {
    match r {
        Some([a, b]) => format!("Some([{}, {}])", f32l(a), f32l(b)),
        None => "None".to_owned(),
    }
}

fn ctrl_opt(c: Option<usize>) -> String {
    match c {
        Some(i) => format!("Some({i})"),
        None => "None".to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{extract, parse};

    #[test]
    fn emits_kinematics_crate_data() {
        let root = parse::load_str(
            "<mujoco model=\"mini\"><compiler angle=\"radian\"/>\
             <worldbody><body name=\"l0\"><joint name=\"j1\" range=\"-1 1\"/></body></worldbody>\
             </mujoco>",
        )
        .unwrap();
        let model = extract::extract(&root).unwrap();
        let out = emit(&model, "mini.xml");

        assert!(out.contains("use kinematics::prelude::{Joint, Quat, Vec3};"));
        assert!(out.contains("pub const NJ: usize = 1;"));
        assert!(out.contains("pub const NAMES: [&str; NJ] = [\"j1\"];"));
        assert!(out.contains("pub const CTRL: [Option<u32>; NJ] = [None];"));
        assert!(out.contains("pub const JOINTS: [Joint; NJ] = ["));
        assert!(out.contains("range: Some([-1.0, 1.0])"));
        assert!(out.contains("pub const TIP_OFFSET: Vec3 = Vec3([0.0, 0.0, 0.0]);"));
        assert!(out.contains("pub const HOME_Q: Option<[f32; NJ]> = None;"));
    }
}
